import pandas as pd
import re
import numpy as np

file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    if isinstance(val, (int, float, np.number)):
        return float(val)
    s = str(val).strip()
    if not s:
        return 0.0
    s_low = s.lower()
    if s_low in ['-', 'na', 'n/a', 'nan']:
        return 0.0
    s_clean = s.replace('₹', '').replace(',', '').strip()
    # Find number and unit
    m = re.match(r'\s*([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?', s_clean)
    if not m:
        # fallback
        m2 = re.search(r'([0-9]*\.?[0-9]+)', s_clean)
        if m2:
            try:
                return float(m2.group(1))
            except:
                return 0.0
        return 0.0
    num_str = m.group(1)
    unit = (m.group(2) or '').lower()
    try:
        num = float(num_str)
    except:
        return 0.0
    if 'cr' in unit:
        mult = 10_000_000
    elif 'lakh' in unit or unit == 'l':
        mult = 100_000
    elif 'k' in unit:
        mult = 1_000
    else:
        mult = 1
    return num * mult

df['Amount_parsed'] = df['Amount'].apply(parse_amount)

# Filter out rows where State is NaN or weird placeholder
valid_states = df['State'].notna() & (df['State'].str.lower() != 'state')
df_valid = df[valid_states]

total = df_valid['Amount_parsed'].sum()
karnataka_total = df_valid.loc[df_valid['State'].str.lower() == 'karnataka', 'Amount_parsed'].sum()

print('Total valid', total)
print('Karnataka valid', karnataka_total)
print('Pct', karnataka_total/total*100 if total else None)

# Also check if any State column has leading/trailing spaces
